import sys

def main():
    data = sys.stdin.read().split()
    s, t = data[0], data[1]
    m = len(t)
    where = {}
    for j in range(m, 0, -1):
        where.setdefault(t[j - 1], []).append(j)
    best = [-1] * (m + 1)
    total = 0
    for r, ch in enumerate(s):
        js = where.get(ch)
        if js:
            for j in js:
                if j == 1:
                    best[1] = r
                else:
                    best[j] = best[j - 1]
        total += r - best[m]
    print(total)

